<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRouter} from 'vue-router';import {api,state,connect,resetServer} from '../state';
const router=useRouter();
// The address field is only needed when the page cannot know its own server:
// the bundled desktop client, or the user pressing "更换服务器".
const editing=ref(false),server=ref(state.server),username=ref(''),password=ref(''),setup=ref(false),checked=ref(false),busy=ref(false),error=ref(state.error);
const askServer=computed(()=>editing.value||(!state.native&&!state.server&&!state.serverReachable&&!state.serverLocked)||(state.native&&!state.serverReachable));
async function check(){busy.value=true;error.value='';try{await connect(server.value,server.value!==location.origin);const s=await api.get<{required:boolean}>('/setup');setup.value=s.required;checked.value=true;editing.value=false}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function changeServer(){editing.value=true;checked.value=false;server.value=state.native?state.server:location.origin;await resetServer();error.value=''}
async function login(){busy.value=true;error.value='';try{if(setup.value)await api.post('/setup',{username:username.value,password:password.value});const session=await api.post('/auth/login',{username:username.value,password:password.value});await api.setSession(session);state.user=session.user;password.value='';await router.replace('/')}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{if(!state.native&&state.server&&!state.serverManual)void check()});
</script>
<template><main class="auth-layout"><section class="auth-intro"><h1>把书放在家里。<br>把阅读带在身边。</h1><p>共享一个书库，每个人拥有自己的书架、进度和笔记。</p></section><section class="panel auth-panel"><h2>{{checked?(setup?'创建家庭管理员':'欢迎回来'):'连接你的书房'}}</h2><form v-if="askServer&&!checked" @submit.prevent="check"><label>服务器地址<input v-model="server" placeholder="http://NAS地址:18089" type="url" required></label><small>网页版默认使用当前站点；桌面客户端请填写 NAS 地址。</small><button :disabled="busy">{{busy?'连接中…':'连接服务器'}}</button><button v-if="!state.native&&state.server" type="button" @click="editing=false;checked=false;void check()">返回当前站点</button></form><form v-else @submit.prevent="login"><label>用户名<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" :autocomplete="setup?'new-password':'current-password'" required :minlength="setup?10:1"></label><small v-if="setup">至少 10 个字符。管理员可以导入图书和添加家庭成员。</small><button class="primary" :disabled="busy">{{busy?'请稍候…':setup?'创建并进入书房':'登录'}}</button></form><p class="server-hint">服务器：<code>{{state.server||'未配置'}}</code><button v-if="!state.native" type="button" class="text-button" @click="changeServer">更换服务器</button></p><p class="error" role="alert" v-if="error">{{error}}</p></section></main></template>
